function getAuthHeaders(sourceId, chapterId, t) {
    const { java } = this;
    const signStr = SALT1 + t + sourceId + chapterId + SALT2;
    const token = java.digestHex(signStr, "SHA-256");

    return {
        "User-Agent": "Mozilla/5.0 (Android 11; Mobile; rv:147.0) Gecko/147.0 Firefox/147.0",
        "x-request-timestamp": t,
        "x-request-token": token,
        "X-Requested-With": "XMLHttpRequest"
    };
}

function decryptChapter(chapterData) {
    const { java } = this;
    const rsa = java.createAsymmetricCrypto("RSA/ECB/PKCS1Padding");
    rsa.setPrivateKey(java.base64DecodeToByteArray(PRIVATE_KEY));

    const AesKeyByte = java.base64DecodeToByteArray(rsa.decryptStr(chapterData.aes_key_encrypt, false));

    const aes = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", AesKeyByte, java.base64DecodeToByteArray(chapterData.iv));

    return aes.decryptStr(java.base64DecodeToByteArray(chapterData.content_encrypt));
}

function getContent(Data) {
    const { java, source } = this;
    const { source_id: sourceId, chapter_id:chapterId, t, sign} = Data;
    const url = `${this.GetUL()}/home/chapter/info?id=${sourceId}&key=${chapterId}&t=${t}&sign=${sign}`;

    const headers = this.getAuthHeaders(sourceId, chapterId, t);
    //java.log(JSON.stringify(headers))
    const response = java.get(url, headers);
    //java.log(response.body())
    const json = JSON.parse(response.body());

    if (json.code === 1) {
        const chapter = json.data.chapter;
        const content = this.decryptChapter(chapter);
        return content;
    } else {
        return "加载失败：" + json.msg;
    }
}

