function loginqt() {
    let base_url = String(getArgument('server') || '').replace(/\/+$/, '');
    let ck = String(cookie.getKey(base_url, "qttoken"));
    if (!ck) {
        java.longToast('\n\n🚫请先登录!')
        return;
    }

    // 阅读器与网页使用不同 Cookie 容器，先换取一次性交接码再打开网页。
    try {
