        let configStr = source.getVariable();
        if (!configStr || configStr.trim() === "") {
            return { host: getServerHost.call(this) };
        }
        let config = JSON.parse(configStr);
        if (!config || !Array.isArray(config) || config.length === 0) {
            return { host: getServerHost.call(this) };
        }
        return config[0] || { host: getServerHost.call(this) };
    } catch (e) {
        return { host: getServerHost.call(this) };
    }
}

