function buildChapterUrl(x, catalog) {
    let { java } = this;
    const isFanqieApp = ['番茄小说', '番茄短剧', '番茄听书', '番茄畅听'].includes(catalog.source);

    let chapterParams = {
        cid: x.cid,
        source: catalog.source
    };

    if (catalog.source === '书旗听书') {
        const itemIdMatch = x.url?.match(/[?&]?item_ids=(\d+)/);
        if (itemIdMatch) {
            chapterParams.bookid = catalog.bookid;
            chapterParams.item_ids = itemIdMatch[1];
        }
    }

    if (!isFanqieApp) {
        chapterParams.url = catalog.url;
    } else {
        chapterParams.book_id = catalog.bookid;
        chapterParams.item_id = x.url?.match(/item_id=(\d+)/)?.[1] || null;
    }

    if (['企鹅看书', 'QQ阅读', '起点'].includes(catalog.source) && x.url && typeof x.url == 'string') {
        let cMatch = x.url.match(/chapterid=(\d+)/);
        if (cMatch) {
            chapterParams.bookid = catalog.bookid;
            chapterParams.chapterid = cMatch[1];
        }
    }

    if (catalog.source == '晋江') {
        let chapterIdMatch = x.url?.match(/chapterId=(\d+)/);
        if (chapterIdMatch) {
            chapterParams.novelId = catalog.bookid;
            chapterParams.chapterId = chapterIdMatch[1];
        }
    }

    if (catalog.source == '半夏') {
        let bjBidMatch = x.url?.match(/bookid=(\d+)/);
        let bjChapterIdMatch = x.url?.match(/chapterid=(\d+)/);
        let novelIdMatch = x.url?.match(/novelId=(\d+)/);
        let chapterIdMatch = x.url?.match(/chapterId=(\d+)/);
        if (bjBidMatch && bjChapterIdMatch) {
            chapterParams.bookid = bjBidMatch[1];
            chapterParams.chapterid = bjChapterIdMatch[1];
        }
        if (novelIdMatch && chapterIdMatch) {
            chapterParams.novelId = novelIdMatch[1];
            chapterParams.chapterId = chapterIdMatch[1];
        }
    }

    if (catalog.source == '七猫小说') {
        chapterParams.qm_url = x.url;
    }

    if (catalog.source == '七猫短剧') {
        chapterParams.qm_id = catalog.bookid;
    }

    if (catalog.source == '七猫听书') {
        chapterParams.book_id = catalog.bookid;
        let qmItemIdMatch = x.url?.match(/item_id=(\d+)/);
        if (qmItemIdMatch) {
            chapterParams.item_id = qmItemIdMatch[1];
        }
    }

    if (catalog.source == '少年梦') {
        let snmBidMatch = x.url?.match(/bid=(\d+)/);
        let snmCidMatch = x.url?.match(/cid=(\d+)/);
        if (snmBidMatch) chapterParams.bookid = snmBidMatch[1];
        if (snmCidMatch) chapterParams.chapterid = snmCidMatch[1];
    }

    let encodedParams = java.base64Encode(JSON.stringify(chapterParams));

    let commentPart = '{"type":"qingci"}';

    if (catalog.source == '七猫小说') {
        const qmBookId = catalog.bookid;
        const qmChapterId = x.url?.match(/item_id=(\d+)/)?.[1] || null;
        if (qmBookId && qmChapterId) {
            const qmCommentUrl = `${getServerHost.call(this)}/qm_comment?book_id=${qmBookId}&item_id=${qmChapterId}&type=chapter`;
            commentPart = `{"type":"qingci","js":"book ? result : '${qmCommentUrl}'"}`;
        }
    } else if (catalog.source == '晋江' && chapterParams.novelId && chapterParams.chapterId) {
        let jjCommentUrl = `${getServerHost.call(this)}/jj_comment?bid=${chapterParams.novelId}&cid=${chapterParams.chapterId}`;
        commentPart = `{"type":"qingci","js":"book ? result : '${jjCommentUrl}'"}`;
    } else if (catalog.source == '半夏' && chapterParams.novelId && chapterParams.chapterId) {
        let bjCommentUrl = `${getServerHost.call(this)}/jj_comment?bid=${chapterParams.novelId}&cid=${chapterParams.chapterId}`;
        if (chapterParams.bookid && chapterParams.chapterid) {
            bjCommentUrl += `&bookid=${chapterParams.bookid}&chapterid=${chapterParams.chapterid}`;
        }
        commentPart = `{"type":"qingci","js":"book ? result : '${bjCommentUrl}'"}`;
    } else if (isFanqieApp) {
        const bookId = catalog.bookid;
        const itemId = x.url?.match(/item_id=(\d+)/)?.[1] || null;
        if (bookId && itemId) {
            const fanqieCommentUrl = `${getServerHost.call(this)}/idea_comment?book_id=${bookId}&item_id=${itemId}&sessionid=${getSessionId.call(this)}`;
            commentPart = `{"type":"qingci","js":"book ? result : '${fanqieCommentUrl}'"}`;
        }
    } else if (catalog.source == '起点' && chapterParams.bookid && chapterParams.chapterid) {
        let qdCommentUrl = `${getServerHost.call(this)}/qd_comment?bid=${chapterParams.bookid}&cid=${chapterParams.chapterid}&para=benzhang`;
        commentPart = `{"type":"qingci","js":"book ? result : '${qdCommentUrl}'"}`;
    }

    return `data:chapterUrl;base64,${encodedParams},${commentPart}`;
