function syncJjShelf(isAdd) {
    let { java, book } = this;
    try {
        if (!book || !book.tocUrl) return;

        let str = String(book.tocUrl);
        let b64 = str.replace(/^data:catalogUrl;base64,/, '');
        let idx = b64.indexOf(',');
        if (idx >= 0) b64 = b64.substring(0, idx);

        let catalog = JSON.parse(java.base64Decode(b64));
        if (!catalog) return;

        if (catalog.source != '晋江') return;

        let bookId = String(catalog.bookid || '');
        if (!bookId) {
            let m = String(catalog.url || '').match(/novelId=(\d+)/);
            if (m) bookId = m[1];
        }
