    return false;
}

function updateConfig(key, value, message, gender) {
    if (gender !== undefined) {
        setConfigs.call(this, {[key]: value, gender: gender});
    } else {
        setConfig.call(this, key, value);
    }
    java.toast(message || "设置已更新");
}

function get_user() {
    try {
        var apiKey = getSecretKey();
        if (!apiKey) {
            java.toast("❌ 未获取到密钥，请先登录");
            return;
        }

        var timestamp = Math.floor(Date.now() / 1000);
        var apiUrl = getServerHost() + '/login';

        var postData = {
            key: apiKey,
            timestamp: timestamp
        };

        var response = java.ajax(apiUrl + "," + JSON.stringify({
            method: "POST",
            body: JSON.stringify(postData),
            headers: {
                "Content-Type": "application/json"
            },
            timeout: 10000
        }));

        var data = JSON.parse(response);

        if (data.data.user) {
            var userInfo = data.data.user;
            var deviceInfo = data.data.device || {};

            var statusDisplay = "";
            switch(userInfo.status) {
                case "正常":
                    statusDisplay = "✅ 正常";
                    break;
                case "会员":
                    statusDisplay = "👑VIP会员";
                    break;
                case "封禁":
                    statusDisplay = "🚫 封禁";
                    break;
                default:
                    statusDisplay = userInfo.status || "正常";
            }

            var email = userInfo.email || "未绑定";
            var maskedEmail = "未绑定";
            if (email !== "未绑定" && email.includes("@")) {
                var parts = email.split("@");
                var username = parts[0];
                var domain = parts[1];
                if (username.length > 2) {
                    maskedEmail = username.substring(0, 2) + "****@" + domain;
                } else {
                    maskedEmail = username + "****@" + domain;
                }
            }

            var nickname = userInfo.nickname || "未设置";
            if (nickname == "未设置") {
                nickname = "👤 " + nickname;
            } else {
                nickname = "👤 " + nickname;
            }

            // 设备信息处理
            var onlineCount = deviceInfo.online_count || 0;
            var deviceLimit = deviceInfo.device_limit || 1;
            var totalCount = deviceInfo.total_count || 0;

            var deviceStatusText = "";
            if (onlineCount >= deviceLimit && totalCount > 0) {
                deviceStatusText = "⚠️ 设备已满（" + onlineCount + "/" + deviceLimit + "）";
            } else if (onlineCount > 0) {
                deviceStatusText = "📱 在线设备：" + onlineCount + "/" + deviceLimit;
            } else {
                deviceStatusText = "📱 当前无设备在线";
            }

            function maskDeviceId(deviceId) {
                if (!deviceId || deviceId.length <= 8) return deviceId || '未知';
                return deviceId.substring(0, 4) + "****" + deviceId.substring(deviceId.length - 4);
            }

            function maskIp(ip) {
                if (!ip) return '';
                if (ip.indexOf('.') !== -1 && ip.indexOf(':') == -1) {
                    var parts = ip.split('.');
                    if (parts.length == 4) return parts[0] + '.' + parts[1] + '.*.*';
                }
                if (ip.indexOf(':') !== -1) {
                    var parts = ip.split(':');
                    var validParts = [];
                    for (var i = 0; i < parts.length; i++) {
                        if (parts[i] !== '') validParts.push(parts[i]);
                    }
                    if (validParts.length >= 4) return validParts.slice(0, 4).join(':') + ':*:*';
                }
                return ip;
            }

            function formatTime(timeStr) {
                if (!timeStr || timeStr == "从未使用") return "未知";
                return timeStr;
            }

            var deviceListText = "";
            var deviceList = (deviceInfo && deviceInfo.list) ? deviceInfo.list : [];
            if (deviceList && deviceList.length > 0) {
                deviceListText = "\n── 设备列表 ──";
                for (var i = 0; i < deviceList.length; i++) {
                    var dev = deviceList[i];
                    var statusIcon = dev.is_online ? '🟢' : '⚫';
                    var maskedId = maskDeviceId(dev.device_id);
                    var maskedIp = maskIp(dev.ip_address);
                    var deviceName = dev.device_name || '未知设备';
                    var trustedIcon = dev.is_trusted ? ' 🔒' : '';
                    var lastSeen = dev.last_seen || '未知';

                    deviceListText += "\n" + statusIcon + " " + maskedId + trustedIcon;
                    deviceListText += "\n   📱 " + deviceName + " | " + (maskedIp || '未知IP');
                    deviceListText += "\n   ⏰ " + lastSeen;
                    if (i < deviceList.length - 1) {
                        deviceListText += "\n";
                    }
                }
            } else {
                deviceListText = "\n── 设备列表 ──\n暂无设备记录";
            }

            var displayContent = 
                "\n────────────\n" +
                "📊 用 户 信 息 📊\n" +
                "────────────\n" +
                nickname + "\n" +
                "────────────\n" +
                "📧 绑定邮箱\n" + maskedEmail + "\n" +
                "────────────\n" +
                "📊 累计阅读\n" + (userInfo.total_usage || 0) + " 次\n" +
                "────────────\n" +
                "📈 今日阅读\n" + (userInfo.today_usage || 0) + " 次\n" +
                "────────────\n" +
                "🔄 账户状态\n" + statusDisplay + "\n" +
                "────────────\n" +
                "📅 注册时间\n" + (userInfo.created_at || "未知") + "\n" +
                "────────────\n" +
                "🖥️ 设备管理\n" +
                "总数：" + totalCount + " | " + deviceStatusText + "\n" +
                (deviceInfo.current_device_online ? "🟢 当前设备在线\n" : "") +
                (deviceInfo.is_kicked ? "⚠️ 设备已被踢出：" + deviceInfo.kicked_reason + "\n" : "") +
