function fq_login() {
    try { 	java.startBrowserAwait("https://fanqienovel.com/main/writer/login", "登录");
    } catch (e) {
        java.toast(e);
    }
    try {
        cookie.removeCookie("snssdk.com");
    } catch (e) {}

    let cookieHeader = String(cookie.getCookie('fanqienovel.com'));

    const match = cookieHeader.match(/sessionid=([^;]+)/);
    java.toast(match);
    let sessionId = match ? match[1] : null;

    let cookieString = sessionId ? "sessionid=" + sessionId : source.getLoginInfoMap()['番茄登录Token'] || "";
    java.toast(cookieString);
    let user;
    try {
        user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
            method: "GET",
            headers: { "Cookie": cookieString }
        }))).data.name;
    } catch (e) { 
        java.log(e); 
    }

    if (!cookieString || cookieString == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败");
        return false;
    }

    java.toast("\n\n欢迎 " + user + "\n登录成功！");
    return true;
}

function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    const manualToken = (source.getLoginInfoMap())['番茄登录Token'];

    const hasValidToken = manualToken && String(manualToken).trim().length > 0;

    if (hasValidToken) {
        java.toast("请手动移除填写的Token");
    } else {
        java.toast("退出登录成功");
    }
}

