<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>头像字体设置</title>
<style>
:root {
    --bg: #0a0a0f;
    --bg-gradient: radial-gradient(ellipse at 30% 20%, #1a1040 0%, #0a0e27 50%, #0d1b3e 100%);
    --text: #e8e8f0;
    --text-secondary: #8888a0;
    --accent: #6c5ce7;
    --accent-glow: rgba(108, 92, 231, 0.4);
    --gold: #f0c040;
}

*{margin:0;padding:0;box-sizing:border-box}

body{
    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Hiragino Sans GB','Microsoft YaHei',sans-serif;
    background:var(--bg);
    background-image:var(--bg-gradient);
    color:var(--text);
    min-height:100vh;
    padding:20px;
    position:relative;
    overflow-x:hidden;
}

.stars-container{
    position:fixed;
    top:0;
    left:0;
    width:100%;
    height:100%;
    pointer-events:none;
    z-index:0;
    overflow:hidden;
}

.star{
    position:absolute;
    border-radius:50%;
    background:#fff;
    animation:twinkle var(--duration) ease-in-out infinite alternate;
    animation-delay:var(--delay);
    opacity:0.3;
}

.star-sm{width:1px;height:1px;--duration:2.5s;opacity:0.3}
.star-md{width:2px;height:2px;--duration:3.2s;opacity:0.5}
.star-lg{width:3px;height:3px;--duration:4.5s;opacity:0.7;box-shadow:0 0 4px rgba(255,255,255,0.3)}
.star-xl{width:4px;height:4px;--duration:5.8s;opacity:0.8;box-shadow:0 0 8px rgba(255,255,255,0.4),0 0 16px rgba(255,255,255,0.1)}

@keyframes twinkle{
    0%{opacity:0.2;transform:scale(0.8)}
    50%{opacity:1;transform:scale(1.2)}
    100%{opacity:0.3;transform:scale(0.9)}
}

.shooting-star{
    position:absolute;
    width:80px;
    height:1px;
    background:linear-gradient(90deg,rgba(255,255,255,0.8),transparent);
    border-radius:1px;
    animation:shoot var(--shoot-duration) linear infinite;
    animation-delay:var(--shoot-delay);
    opacity:0;
    top:var(--top);
    left:var(--left);
}

.shooting-star::after{
    content:'';
    position:absolute;
    top:-2px;
    right:0;
    width:4px;
    height:4px;
    border-radius:50%;
    background:#fff;
    box-shadow:0 0 6px rgba(255,255,255,0.6);
}

@keyframes shoot{
    0%{transform:translate(0,0) rotate(-35deg);opacity:0}
    5%{opacity:1}
    15%{opacity:1}
    20%{opacity:0;transform:translate(-350px,250px) rotate(-35deg)}
    100%{opacity:0}
}

.particles{
    position:fixed;
    top:0;
    left:0;
    width:100%;
    height:100%;
    pointer-events:none;
    z-index:1;
}

.particle{
    position:absolute;
    border-radius:50%;
    animation:floatUp var(--duration) linear infinite;
    animation-delay:var(--delay);
    opacity:0;
    background:var(--color);
    box-shadow:0 0 12px var(--color);
}

@keyframes floatUp{
    0%{opacity:0;transform:translateY(100vh) scale(0.2)}
    10%{opacity:0.45}
    90%{opacity:0.45}
    100%{opacity:0;transform:translateY(-100px) scale(1)}
}

.container{
    width:100%;
    max-width:680px;
    margin:0 auto;
    position:relative;
    z-index:10;
    background:rgba(10,14,27,0.45);
    backdrop-filter:blur(20px);
    -webkit-backdrop-filter:blur(20px);
    border-radius:28px;
    border:1px solid rgba(255,255,255,0.1);
    box-shadow:0 20px 60px rgba(0,0,0,0.6),0 0 80px rgba(108,92,231,0.15);
    overflow:hidden;
    animation:cardIn 0.8s cubic-bezier(0.22,0.61,0.36,1);
}

@keyframes cardIn{
    from{opacity:0;transform:translateY(30px) scale(0.98)}
    to{opacity:1;transform:translateY(0) scale(1)}
}

.header{
    padding:28px 28px 20px;
    border-bottom:1px solid rgba(255,255,255,0.08);
    background:rgba(255,255,255,0.02);
    text-align:center;
}

.header h1{
    font-size:24px;
    font-weight:700;
    letter-spacing:0.5px;
    color:rgba(255,255,255,0.95);
    text-shadow:0 0 30px rgba(108,92,231,0.5);
}

.header p{
    font-size:13px;
    color:rgba(255,255,255,0.55);
    margin-top:6px;
    letter-spacing:1px;
}

.section{
    padding:24px 28px;
    border-bottom:1px solid rgba(255,255,255,0.06);
}

.section:last-of-type{
    border-bottom:none;
}

.section-title{
    font-size:14px;
    font-weight:600;
    color:rgba(255,255,255,0.85);
    margin-bottom:16px;
    letter-spacing:0.3px;
    text-transform:uppercase;
    display:flex;
    align-items:center;
    gap:8px;
}

.title-dot{
    width:8px;
    height:8px;
    border-radius:50%;
    background:var(--accent);
    box-shadow:0 0 8px var(--accent-glow);
    display:inline-block;
}

.title-dot.gold{
    background:var(--gold);
    box-shadow:0 0 8px rgba(240,192,64,0.4);
}

.avatar-section-title{
    font-size:13px;
    color:rgba(255,255,255,0.7);
    margin-bottom:12px;
    letter-spacing:0.5px;
    display:flex;
    align-items:center;
    gap:8px;
    flex-wrap:wrap;
}

.selection-indicator{
    font-size:11px;
    padding:4px 10px;
    border-radius:20px;
    background:rgba(108,92,231,0.2);
    border:1px solid rgba(108,92,231,0.4);
    color:rgba(255,255,255,0.9);
    letter-spacing:0.5px;
}

.avatar-grid{
    display:grid;
    grid-template-columns:repeat(4,1fr);
    gap:12px;
}

.avatar-item{
    padding:12px 8px;
    border:2px solid rgba(255,255,255,0.12);
    border-radius:16px;
    background:rgba(255,255,255,0.03);
    cursor:pointer;
    transition:all 0.3s cubic-bezier(0.22,0.61,0.36,1);
    text-align:center;
    position:relative;
}

.avatar-item:hover{
    border-color:rgba(255,255,255,0.3);
    background:rgba(255,255,255,0.08);
    transform:translateY(-2px);
    box-shadow:0 8px 24px rgba(0,0,0,0.3);
}

.avatar-item.selected{
    border-color:var(--accent);
    background:rgba(108,92,231,0.15);
    box-shadow:0 0 24px rgba(108,92,231,0.3);
}

.avatar-item.selected::after{
    content:'✓';
    position:absolute;
    top:6px;
    right:8px;
    font-size:14px;
    color:#fff;
    background:var(--accent);
    border-radius:50%;
    width:20px;
    height:20px;
    display:flex;
    align-items:center;
    justify-content:center;
    box-shadow:0 0 8px rgba(108,92,231,0.6);
}

.avatar-img-wrapper{
    width:64px;
    height:64px;
    margin:0 auto 8px;
    border-radius:50%;
    overflow:hidden;
    border:2px solid rgba(255,255,255,0.2);
    background:rgba(255,255,255,0.05);
}

.avatar-item.selected .avatar-img-wrapper{
    border-color:var(--accent);
    box-shadow:0 0 16px rgba(108,92,231,0.4);
}

.avatar-item img{
    width:100%;
    height:100%;
    object-fit:cover;
    border-radius:50%;
    display:block;
}

.avatar-item span{
    display:block;
    font-size:11px;
    color:rgba(255,255,255,0.7);
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
}

.font-grid{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:12px;
}

.font-btn{
    padding:14px 10px;
    border:1px solid rgba(255,255,255,0.12);
    border-radius:14px;
    background:rgba(255,255,255,0.03);
    cursor:pointer;
    transition:all 0.3s cubic-bezier(0.22,0.61,0.36,1);
    text-align:center;
    font-size:13px;
    font-weight:500;
    color:rgba(255,255,255,0.7);
}

.font-btn:hover{
    border-color:rgba(255,255,255,0.3);
    background:rgba(255,255,255,0.08);
    transform:translateY(-2px);
    box-shadow:0 8px 24px rgba(0,0,0,0.3);
}

.font-btn.selected{
    background:rgba(108,92,231,0.2);
    border-color:var(--accent);
    color:#fff;
    box-shadow:0 4px 16px rgba(108,92,231,0.3);
}

.bubble-slider-wrapper{
    position:relative;
    overflow:hidden;
    padding:4px 0;
}

.bubble-slider{
    display:flex;
    gap:12px;
    overflow-x:auto;
    scroll-snap-type:x mandatory;
    -webkit-overflow-scrolling:touch;
    scrollbar-width:none;
    -ms-overflow-style:none;
    padding:8px 4px;
}

.bubble-slider::-webkit-scrollbar{
    display:none;
}

.bubble-slide{
    flex:0 0 auto;
    scroll-snap-align:center;
    width:110px;
    padding:14px 10px;
    border:2px solid rgba(255,255,255,0.12);
    border-radius:16px;
    background:rgba(255,255,255,0.03);
    cursor:pointer;
    transition:all 0.3s cubic-bezier(0.22,0.61,0.36,1);
    text-align:center;
    position:relative;
}

.bubble-slide:hover{
    border-color:rgba(255,255,255,0.3);
    background:rgba(255,255,255,0.08);
    transform:translateY(-2px);
    box-shadow:0 8px 24px rgba(0,0,0,0.3);
}

.bubble-slide.selected{
    border-color:var(--accent);
    background:rgba(108,92,231,0.15);
    box-shadow:0 0 24px rgba(108,92,231,0.3);
}

.bubble-slide.selected::after{
    content:'✓';
    position:absolute;
    top:6px;
    right:8px;
    font-size:14px;
    color:#fff;
    background:var(--accent);
    border-radius:50%;
    width:20px;
    height:20px;
    display:flex;
    align-items:center;
    justify-content:center;
    box-shadow:0 0 8px rgba(108,92,231,0.6);
}

.bubble-preview{
    width:100%;
    max-width:70px;
    margin:0 auto 8px;
    padding:8px 12px;
    border-radius:16px;
    border:1px solid #cccccc;
    font-size:12px;
    display:inline-block;
    white-space:nowrap;
    overflow:hidden;
}

.bubble-name{
    display:block;
    font-size:12px;
    color:rgba(255,255,255,0.8);
    font-weight:500;
    margin-top:4px;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
}

.bubble-desc{
    display:block;
    font-size:10px;
    color:rgba(255,255,255,0.4);
    margin-top:2px;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
}

.bubble-hint{
    text-align:center;
    font-size:10px;
    color:rgba(255,255,255,0.3);
    margin-top:8px;
    letter-spacing:1px;
}

.empty-state{
    text-align:center;
    padding:40px 20px;
    color:rgba(255,255,255,0.4);
    font-size:14px;
    letter-spacing:1px;
}

.switch-section{
    padding:24px 28px;
    border-bottom:1px solid rgba(255,255,255,0.06);
}

.switch-row{
    display:flex;
    align-items:center;
    justify-content:space-between;
    padding:8px 0;
}

.switch-label{
    font-size:14px;
    color:rgba(255,255,255,0.85);
    display:flex;
    align-items:center;
    gap:8px;
}

.switch-desc{
    font-size:12px;
    color:rgba(255,255,255,0.5);
    margin-top:4px;
}

.switch{
    position:relative;
    width:52px;
    height:28px;
    cursor:pointer;
}

.switch input{
    opacity:0;
    width:0;
    height:0;
}

.switch-slider{
    position:absolute;
    top:0;
    left:0;
    right:0;
    bottom:0;
    background:rgba(255,255,255,0.15);
    border-radius:28px;
    transition:all 0.3s cubic-bezier(0.22,0.61,0.36,1);
    border:1px solid rgba(255,255,255,0.2);
}

.switch-slider::before{
    content:'';
    position:absolute;
    width:22px;
    height:22px;
    left:2px;
    bottom:2px;
    background:#fff;
    border-radius:50%;
    transition:all 0.3s cubic-bezier(0.22,0.61,0.36,1);
    box-shadow:0 2px 8px rgba(0,0,0,0.3);
}

.switch input:checked + .switch-slider{
    background:var(--accent);
    border-color:var(--accent);
    box-shadow:0 0 16px rgba(108,92,231,0.5);
}

.switch input:checked + .switch-slider::before{
    transform:translateX(24px);
}

.clear-area{
    padding:0 28px 28px;
}

.clear-btn{
    width:100%;
    padding:12px;
    border:1px dashed rgba(255,255,255,0.25);
    border-radius:14px;
    background:transparent;
    font-size:13px;
    color:rgba(255,255,255,0.5);
    cursor:pointer;
    transition:all 0.3s;
}

.clear-btn:hover{
    border-color:rgba(255,255,255,0.5);
    color:#fff;
    background:rgba(255,255,255,0.05);
}

.action-hint{
    text-align:center;
    font-size:12px;
    color:rgba(255,255,255,0.35);
    padding:16px 28px 20px;
    border-top:1px solid rgba(255,255,255,0.06);
    letter-spacing:1px;
}

@media (max-width:480px){
    .avatar-grid{grid-template-columns:repeat(3,1fr)}
    .font-grid{grid-template-columns:repeat(3,1fr)}
    .section{padding:18px 16px}
    .header{padding:20px 16px}
    .avatar-img-wrapper{width:52px;height:52px}
    .bubble-slide{width:100px}
}
</style>
</head>
<body>
<div class="stars-container" id="starsContainer"></div>
<div class="particles" id="particles"></div>

<div class="container">
<div class="header">
<h1>✦ 头像与字体设置 ✦</h1>
<p>左右头像可以独立选择</p>
</div>

<div class="switch-section">
<div class="switch-row">
<div>
<div class="switch-label"><span class="title-dot"></span>对话生图功能</div>
<div class="switch-desc">开启后自动将对话内容转换为图片</div>
</div>
<label class="switch">
<input type="checkbox" id="dialogueSwitch" onchange="toggleDialogue(this)" ` + (dialogue == 'true' ? 'checked' : '') + `>
<span class="switch-slider"></span>
</label>
</div>
</div>

<div class="section">
<div class="section-title"><span class="title-dot"></span>气泡样式 <span style="font-size:11px;color:rgba(255,255,255,0.4);text-transform:none;">← 左右滑动选择 →</span></div>
<div class="bubble-slider-wrapper">
<div class="bubble-slider" id="bubbleSlider">` + bubbleHtml + `</div>
</div>
<div class="bubble-hint">左右滑动查看更多样式</div>
</div>

<div class="section">
<div class="section-title"><span class="title-dot"></span>头像选择</div>
` + avatarHtml + `
</div>
<div class="section">
<div class="section-title"><span class="title-dot"></span>字体选择</div>
<div class="font-grid">` + fontHtml + `</div>
</div>
<div id="result-output" style="display:none;">` + tx1 + '|' + tx2 + '|' + ttf + '|' + dialogue + '|' + bubble + `</div>
<div class="clear-area">
<button onclick="clearAll()" class="clear-btn">恢复默认设置</button>
</div>
<div class="action-hint">✦ 选择完成后点击右上角确认生效 ✦</div>
</div>
<script>
var selectedFont = '` + ttf + `';
var selectedTx1 = '` + tx1 + `';
var selectedTx2 = '` + tx2 + `';
var selectedDialogue = '` + dialogue + `';
var selectedBubble = '` + bubble + `';

function selectFont(id) {
    selectedFont = id;
    document.querySelectorAll('.font-btn').forEach(function(b) {
        b.classList.remove('selected');
        if (b.getAttribute('data-id') == id) { b.classList.add('selected'); }
    });
    updateResult();
}

function selectAvatar(side, avatarName, element) {
    if (side == 'left') {
        selectedTx1 = avatarName;
        document.getElementById('left-indicator').textContent = avatarName;
    } else {
        selectedTx2 = avatarName;
        document.getElementById('right-indicator').textContent = avatarName;
    }

    var selector = element.closest('.avatar-selector');
    selector.querySelectorAll('.avatar-item').forEach(function(item) {
        if (item == element) {
            item.classList.add('selected');
        } else {
            item.classList.remove('selected');
        }
    });

    updateResult();
}

function selectBubble(id, element) {
    selectedBubble = id;
    document.querySelectorAll('.bubble-slide').forEach(function(b) {
        b.classList.remove('selected');
        if (b.getAttribute('data-id') == id) { b.classList.add('selected'); }
    });
    updateResult();
}

function toggleDialogue(checkbox) {
    selectedDialogue = checkbox.checked ? 'true' : '';
    updateResult();
}

function updateResult() {
    document.getElementById('result-output').textContent = selectedTx1 + '|' + selectedTx2 + '|' + selectedFont + '|' + selectedDialogue + '|' + selectedBubble;
}

function clearAll() {
    selectedFont = '霞鹜文楷';
    selectedTx1 = '';
    selectedTx2 = '';
    selectedDialogue = '';
    selectedBubble = 'default';
    document.getElementById('left-indicator').textContent = '未选择';
    document.getElementById('right-indicator').textContent = '未选择';
    document.getElementById('dialogueSwitch').checked = false;
    document.querySelectorAll('.font-btn').forEach(function(b) {
        b.classList.remove('selected');
        if (b.getAttribute('data-id') == '霞鹜文楷') { b.classList.add('selected'); }
    });
    document.querySelectorAll('.avatar-item').forEach(function(item) {
        item.classList.remove('selected');
    });
    document.querySelectorAll('.bubble-slide').forEach(function(item) {
        item.classList.remove('selected');
        if (item.getAttribute('data-id') == 'default') { item.classList.add('selected'); }
    });
    updateResult();
}

document.querySelectorAll('.avatar-selector').forEach(function(selector) {
    var side = selector.getAttribute('data-side');
    var selectedName = side == 'left' ? selectedTx1 : selectedTx2;
    if (selectedName) {
        selector.querySelectorAll('.avatar-item').forEach(function(item) {
            if (item.getAttribute('data-avatar') == selectedName) {
                item.classList.add('selected');
            }
        });
    }
});

document.querySelectorAll('.bubble-slide').forEach(function(item) {
    if (item.getAttribute('data-id') == selectedBubble) {
        item.classList.add('selected');
    }
});

var bubbleSlider = document.getElementById('bubbleSlider');
if (bubbleSlider) {
    var selectedBubbleElement = bubbleSlider.querySelector('.bubble-slide.selected');
    if (selectedBubbleElement) {
        selectedBubbleElement.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
    }
}

(function() {
    var starsContainer = document.getElementById('starsContainer');
    if (!starsContainer) return;

    starsContainer.innerHTML = '';

    var starCount = 150;
    var starSizes = ['star-sm', 'star-sm', 'star-sm', 'star-sm', 'star-md', 'star-md', 'star-lg', 'star-xl'];

    for (var i = 0; i < starCount; i++) {
        var star = document.createElement('div');
        var sizeClass = starSizes[Math.floor(Math.random() * starSizes.length)];
        star.className = 'star ' + sizeClass;

        star.style.left = Math.random() * 100 + '%';
        star.style.top = Math.random() * 100 + '%';

        var duration = 1.5 + Math.random() * 4.5;
        star.style.setProperty('--duration', duration + 's');
        star.style.setProperty('--delay', Math.random() * 5 + 's');

        star.style.opacity = 0.2 + Math.random() * 0.6;

        starsContainer.appendChild(star);
    }

    var shootingStars = [
        { top: '5%', left: '80%', delay: 0, duration: 6 },
        { top: '15%', left: '70%', delay: 4, duration: 8 },
        { top: '30%', left: '85%', delay: 9, duration: 7 },
        { top: '45%', left: '75%', delay: 14, duration: 9 },
        { top: '60%', left: '90%', delay: 20, duration: 6.5 },
        { top: '75%', left: '80%', delay: 26, duration: 7.5 }
    ];

    shootingStars.forEach(function(s) {
        var meteor = document.createElement('div');
        meteor.className = 'shooting-star';
        meteor.style.setProperty('--top', s.top);
        meteor.style.setProperty('--left', s.left);
        meteor.style.setProperty('--shoot-duration', s.duration + 's');
        meteor.style.setProperty('--shoot-delay', s.delay + 's');
        meteor.style.transform = 'rotate(' + (-25 + Math.random() * 20) + 'deg)';
        starsContainer.appendChild(meteor);
    });
})();

(function() {
    var particlesContainer = document.getElementById('particles');
    var colors = ['#6c5ce7', '#a78bfa', '#f0c040', '#fbbf24', '#00d2ff', '#7c3aed'];
    for (var j = 0; j < 20; j++) {
        var particle = document.createElement('div');
        particle.className = 'particle';
        particle.style.left = Math.random() * 100 + '%';
        var size = Math.random() * 3 + 2;
        particle.style.width = size + 'px';
        particle.style.height = size + 'px';
        var color = colors[Math.floor(Math.random() * colors.length)];
        particle.style.setProperty('--color', color);
        particle.style.boxShadow = '0 0 ' + (Math.random() * 10 + 6) + 'px ' + color;
        particle.style.setProperty('--duration', Math.random() * 12 + 10 + 's');
        particle.style.setProperty('--delay', Math.random() * 8 + 's');
        particlesContainer.appendChild(particle);
    }
})();
</script>
</body>
</html>`;

        var base64 = `data:text/html;base64,${java.base64Encode(html)}`;
