function SourceSelector() {
    try {
        var config = getConfig.call(this);

        var typeToItems = {};
        var typeLabels = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
        var typeIcons = {
            novel: 'fa-solid fa-book-open',
            audio: 'fa-solid fa-headphones',
            comic: 'fa-solid fa-images',
            video: 'fa-solid fa-clapperboard'
        };
        var typeKeywords = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
        var typeOrder = ['novel', 'audio', 'comic', 'video'];

        try {
            var apiUrl = getServerHost() + '/api/get_config';
            var resp = JSON.parse(java.ajax(apiUrl));
            if (resp && Array.isArray(resp)) {
                resp.forEach(function (item) {
                    if (!item.name || !item.key) return;
                    var t = item.type || 'novel';
                    if (!typeToItems[t]) typeToItems[t] = [];
                    typeToItems[t].push({
                        name: item.name,
                        key: item.key,
                        free: item.free || ''
                    });
                });
