  padding: 0 16px 16px;
}

.custom-styles-container {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.empty-custom-styles {
  text-align: center;
  padding: 20px;
  color: var(--text-secondary);
  font-size: 13px;
  background: var(--bg-elevated);
  border-radius: 12px;
  border: 1px dashed var(--border-color);
}

/* 自定义样式卡片 */
.custom-style-card {
  background: var(--bg-elevated);
  border-radius: 12px;
  padding: 12px;
  border: 1px solid var(--border-color);
}

.custom-style-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 10px;
}

.style-name-input {
  flex: 1;
  padding: 6px 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 6px;
}

.style-actions {
  display: flex;
  gap: 6px;
}

.style-btn {
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  transition: all 0.2s ease;
}

.preview-btn {
  background: rgba(45, 157, 120, 0.1);
  color: var(--color-primary);
}

.preview-btn:hover {
  background: rgba(45, 157, 120, 0.2);
}

.delete-btn {
  background: rgba(244, 67, 54, 0.1);
  color: #f44336;
}

.delete-btn:hover {
  background: rgba(244, 67, 54, 0.2);
}

.style-code-textarea {
  width: 100%;
  padding: 10px;
  font-size: 12px;
  font-family: monospace;
  color: var(--text-primary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  resize: vertical;
  min-height: 80px;
  box-sizing: border-box;
  margin-bottom: 10px;
}

.style-preview-small {
  display: flex;
  justify-content: center;
  padding: 10px;
  background: var(--bg-card);
  border-radius: 8px;
}

.preview-svg-container svg {
  width: 50px;
  height: 45px;
}

.preview-section {
  padding: 20px;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border-color);
}

.preview-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.preview-title i {
  color: var(--color-primary);
}

.preview-container {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  align-items: center;
  min-height: 150px;
}

.preview-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px;
  background: var(--bg-card);
  border-radius: 12px;
  border: 1px solid var(--border-color);
}

.preview-item.selected {
  border-color: var(--color-primary);
  background: rgba(45, 157, 120, 0.05);
}

.preview-item svg {
  width: 60px;
  height: 54px;
  cursor: pointer;
  transition: transform 0.2s ease;
}

.preview-item svg:hover {
  transform: scale(1.1);
}

.preview-item .preview-label {
  font-size: 11px;
  color: var(--text-secondary);
  text-align: center;
}

.preview-item.selected .preview-label {
  color: var(--color-primary);
  font-weight: 600;
}

/* 高亮文本 */
.highlight {
  color: var(--color-primary);
  font-weight: 700;
}

.highlight-red {
  color: #ef4444;
  font-weight: 700;
}

/* Toast提示样式 */
.toast-container {
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  border-radius: 12px;
  background: var(--bg-card);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  border: 1px solid var(--border-color);
  min-width: 200px;
  max-width: 320px;
  animation: toastSlideIn 0.3s ease-out;
}

.toast.fade-out {
  animation: toastFadeOut 0.3s ease-out forwards;
}

@keyframes toastSlideIn {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes toastFadeOut {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(20px);
  }
}

.toast-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.toast-icon.success {
  background: rgba(76, 175, 80, 0.1);
  color: #4CAF50;
}

.toast-icon.error {
  background: rgba(244, 67, 54, 0.1);
  color: #F44336;
}

.toast-icon.warning {
  background: rgba(255, 193, 7, 0.1);
  color: #FFC107;
}

.toast-icon.info {
  background: rgba(33, 150, 243, 0.1);
  color: #2196F3;
}

.toast-icon.loading {
  background: rgba(45, 157, 120, 0.1);
  color: var(--color-primary);
}

.toast-content {
  flex: 1;
  font-size: 14px;
  color: var(--text-primary);
  font-weight: 500;
}



@keyframes spin {
  to { transform: rotate(360deg); }
}

/* 保存按钮加载状态 */
.save-style-btn.loading {
  opacity: 0.7;
  pointer-events: none;
}

.save-style-btn.loading i {
  display: none;
}

.save-style-btn.loading .btn-text {
  display: none;
}


/* 响应式 */
@media (max-width: 600px) {
  .container {
    padding: 12px;
  }

  .main-card {
    border-radius: 16px;
  }

  .tip-alert {
    margin: 16px;
    padding: 14px 16px;
  }

  .setting-item {
    padding: 14px;
  }

  .color-picker-wrapper {
    flex-direction: column;
    align-items: flex-end;
  }
}
</style>
</head>
