  z-index: 1;
}

.tip-alert p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin: 0;
  position: relative;
  z-index: 1;
}

.tip-alert .highlight-text {
  color: #ea580c;
