        ${JSON.stringify(data || {"小说":"全部","听书":"全部","漫画":"全部","短剧":"全部","搜索模式":"小说","显示图片":"true","完整简介":"true","书籍讨论":"false","同步书架":"false","同步弹窗":"true","网络模式":"服务器","强制搜索":"false","目录显示来源":"true"})}
