        body = java.startBrowserAwait(`data:text/html;base64,${java.base64Encode(html)}`, '光遇书源设置', false).body();
    } catch (e) {
        let islyc = this.checkEnv();
        if (islyc == "安卓") {
            java.longToast("\n当前软件版本过低，请更新软件，或者使用底部备用设置方案~");
        } else {
            java.longToast("\n请点击页面右上角√才能设置成功哦~");
        }
        return;
    }

    let settings = {};
    try {
        const getSpanText = (spanId) => {
            const regex = new RegExp('id="' + spanId + '"\s*>\s*([^<]*?)\s*<\/span>');
            const match = body.match(regex);
            return match ? match[1].trim() : "";
        };
        settings = {
            '搜索模式': getSpanText('searchModeValue'),
            '显示图片': getSpanText('showImageSwitchValue'),
            '完整简介': getSpanText('fullDescSwitchValue'),
            '书籍讨论': getSpanText('bookDiscussionSwitchValue'),
            '同步书架': getSpanText('syncBookshelfSwitchValue'),
            '同步弹窗': getSpanText('syncPopupSwitchValue'),
            '网络模式': getSpanText('networkModeValue'),
            '强制搜索': getSpanText('forceSearchSwitchValue'),
            '目录显示来源': getSpanText('showSourceInTocValue'),
            '小说': getSpanText('novelSource'),
            '听书': getSpanText('audioSource'),
            '漫画': getSpanText('comicSource'),
            '短剧': getSpanText('dramaSource'),
        };
        const settingsText = Object.keys(settings).map(key => `${key}: ${settings[key]}`).join('\n');
        java.longToast("\n" + settingsText);

    } catch (e) {
        settings = {
            '搜索模式': '小说',
            '显示图片': 'true',
            '完整简介': 'true',
            '书籍讨论': 'false',
            '同步书架': 'false',
            '同步弹窗': 'true',
            '网络模式': '服务器',
            '强制搜索': 'false',
            '目录显示来源': 'true',
            '小说': '全部',
            '听书': '全部',
            '漫画': '全部',
            '短剧': '全部',
        };
    }
    this.setVariable("更多设置", settings, false)
}

