var LK_API = 'https://api.lightnovel.fun/proxy/api';
var LK_HEADERS = {'User-Agent': 'Dart/3.11 (dart:io)', 'Content-Type': 'application/json'};

function lkUrl(path, d, key, fresh) {
    d = d || {};
    d.security_key = key || '';
    var b = {is_encrypted: 0, platform: 'android', client: 'app', gz: 0, d: d};
    if (fresh) {
        b.ts = Math.floor(Date.now() / 1000);
        b.nonce = (Math.random().toString(36) + Math.random().toString(36)).replace(/0\./g, '').slice(0, 12);
    }
    var body = JSON.stringify(b);
    return LK_API + path + ',' + JSON.stringify({method: 'POST', body: body, headers: LK_HEADERS});
}

function lkKey(source) {
    try { return String(source.get('lk_key') || ''); } catch (e) { return ''; }
}

function lkZhOn(source) {
    try { return String(source.get('lk_zh') || '') == '1'; } catch (e) { return false; }
}

function lkCoinOn(source) {
    try { return String(source.get('lk_coin') || '') == '1'; } catch (e) { return false; }
}

function lkSearch(q, page) {
    return lkUrl('/bff/apk-search-result-v1', {page: page - 1, pageSize: 20, q: String(q), source: 'manual', sort: 'relevance'});
}

function lkList(payload, page, work, sort, status) {
    var d = {};
    try { d = JSON.parse(decodeURIComponent(payload)) || {}; } catch (e) {}
    d.page = page - 1;
    d.pageSize = 20;
    d.source = 'category_tag';
    d.sort = sort || 'relevance';
    if (d.q == null) d.q = '';
    if (work) d.work_type = work;
    if (status && status != 'all') d.status_bucket = status;
    return lkUrl('/bff/apk-search-result-v1', d);
}

function lkTaxonomy() {
    return lkUrl('/bff/apk-search-taxonomy-v1', {});
}

function lkRank(scene, page) {
    return lkUrl('/bff/book-rank-list-v1', {page: page - 1, pageSize: 20, rank_scene: scene});
}

function lkDetail(id) {
    return lkUrl('/new-content-read/get-book-detail', {book_id: parseInt(id)});
}

function lkChapter(id, key) {
    return lkUrl('/new-content-read/get-chapter-detail', {chapter_id: parseInt(id), with_body: 1}, key);
}

function lkStatus(o) {
    if (o.serial_status == 'completed' || o.is_completed == 1) return '已完结';
    if (o.serial_status == 'serializing') return '连载中';
    return '';
}

function lkTags(o) {
    var r = [];
    (o.tags || []).forEach(function (t) {
        t = String(typeof t == 'string' ? t : (t.name || t.tag_name || ''));
        if (t && r.indexOf(t) < 0) r.push(t);
    });
    return r;
}

function lkKind(o) {
    var r = [];
    if (o.work_type && o.work_type.text) r.push(o.work_type.text);
    var st = lkStatus(o);
    if (st) r.push(st.replace('已', '').replace('中', ''));
    return r.concat(lkTags(o)).join(',');
}

function lkBbcode(t) {
    t = String(t)
        .replace(/\[input_pos\][\s\S]*?\[\/input_pos\]/gi, '')
        .replace(/\[i=s\][\s\S]*?\[\/i\]/gi, '')
        .replace(/\[img\]\s*(https?:\/\/[^\[\s]+?)\s*\[\/img\]/gi, '<img src="$1">');
    ['justify', 'left', 'right', 'center', 'align', 'font', 'size', 'color', 'backcolor',
     'b', 'i', 'u', 's', 'indent', 'float', 'quote', 'code', 'url', 'email',
     'list', 'table', 'tr', 'td', 'p', 'ruby', 'rp', 'rt', 'media', 'attach'].forEach(function (n) {
        t = t.replace(new RegExp('\\[' + n + '=[^\\]\\n]{1,80}\\]', 'gi'), '');
        if (new RegExp('\\[\\/' + n + '\\]', 'i').test(t)) {
            t = t.replace(new RegExp('\\[\\/?' + n + '\\]', 'gi'), '');
        }
    });
    return t;
}

function lkIntro(o) {
    var t = lkBbcode(String(o.summary || o.summary_short || '').replace(/\\n/g, '\n').replace(/\r/g, ''))
        .replace(/[—－\-_=]{5,}/g, '')
        .replace(/[ \t\u3000]*\n[\s\u3000]*/g, '\n')
        .trim();
    return /^[\s.…]*$/.test(t) ? '' : t;
}

function lkTime(t) {
    return String(t || '').replace(/:\d\d$/, '');
}

function lkInfo(o) {
    var uniq = function (v, i, a) { return v && a.indexOf(v) == i; };
    var words = parseInt(o.word_count) || 0;
    var ws = words >= 10000 ? (words / 10000).toFixed(1) + '万字' : (words ? words + '字' : '');
    var size = (o.volume_count ? o.volume_count + '卷' : '') + (o.chapter_count ? o.chapter_count + '章' : '');
    var posters = (o.poster_users || (o.poster_user ? [o.poster_user] : [])).map(function (u) { return String(u.nickname || ''); }).filter(uniq);
    var rating = o.rating_displayable == 1 && o.rating_score_10 ? o.rating_score_10 + '（' + o.rating_count + '人评分）' : '';
    var L = [];
    var add = function (icon, label, val) { if (val) L.push('\u3000\u3000' + icon + ' ' + label + '：' + val); };
    add('📕', '书名', String(o.title || ''));
    add('👤', '作者', String(o.author_name || ''));
    add('📤', '发布', posters.join(' · '));
    add('🗂️', '类型', o.work_type && o.work_type.text);
    add('📊', '字数', [ws, lkStatus(o), size].filter(uniq).join(' · '));
    add('🔖', '标签', lkTags(o).join(' · '));
    add('⭐', '评分', rating);
    add('👀', '在读', o.active_reader_count ? o.active_reader_count + '人' : '');
    add('🕐', '更新', lkTime(o.updated_at));
    var desc = lkIntro(o);
    if (desc) {
        L.push('\u3000\u3000\u200b');
        L.push('\u3000\u3000📜 简介：');
        L.push('\u3000\u3000' + desc.replace(/\n/g, '\n\u3000\u3000'));
    }
    L.push('\u3000\u3000\u200b');
    L.push('\u3000\u3000📍 书籍状态：正常');
    return L.join('\n');
}

function lkBook(o, full) {
    return JSON.stringify({
        name: String(o.title || ''),
        author: String(o.author_name || ''),
        kind: lkKind(o),
        intro: full ? lkInfo(o) : (lkIntro(o) || '暂无简介'),
        cover: String(o.cover_url || ''),
        words: String(o.word_count || ''),
        last: o.updated_at ? '更新于 ' + String(o.updated_at).slice(0, 10) : '',
        url: lkDetail(o.book_id)
    });
}

function lkLockTip(d, loggedIn, coinOn, err) {
    var L = [];
    if (d.brave_required == 1 || d.access_type == 'brave') {
        L.push('🔒 本章需要「勇者」身份才能阅读。');
    } else if (d.access_type == 'coin') {
        var pct = parseInt(d.preview_percent || d.free_node) || 0;
        L.push('🔒 本章为付费章节' + (d.coin_price > 0 ? '，需 ' + d.coin_price + ' 轻币解锁' : '') + '。');
        if (pct) L.push('以上为试读内容（约 ' + pct + '%）。');
        if (err) L.push('自动解锁失败：' + err);
        else if (!loggedIn) L.push('请先在书源登录页登录，并开启「花费轻币」后重新加载本章。');
        else if (!coinOn) L.push('可在书源登录页开启「花费轻币」后重新加载本章。');
    } else {
        L.push('🔒 本章暂时无法阅读（' + (d.access_type || '未知原因') + '）。');
        if (!loggedIn) L.push('当前未登录，可在书源登录页登录后重试。');
    }
    return L.map(function (x) { return '<p>' + x + '</p>'; }).join('\n');
}

function lkHtml(d) {
    var html = String((d.body_snapshot && d.body_snapshot.body_html) || (d.render_preview && d.render_preview.body_html) || '');
    html = html.replace(/<p[^>]*>/gi, '<p>').replace(/<\/?span[^>]*>/gi, '')
        .replace(/&lt;\/?p(?:\s[\s\S]*?)?&gt;/gi, '')
        .replace(/<p>\s*\*\*/g, '<p>').replace(/\*\*\s*<\/p>/g, '</p>');
    html = html.replace(/<a\b[^>]*?href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, function (m, url, label) {
        var t = label.replace(/<[^>]+>/g, '').trim();
        return !t || t == url ? url : t + '：' + url;
    });
    return lkBbcode(html).replace(/<p>[\s\u3000\u00a0]*<\/p>/g, '').trim();
}

