var d = JSON.parse(result).data || {};
var key = lkKey(source);
var coinOn = lkCoinOn(source);
var err = '';
function reload() {
    try { d = JSON.parse(java.ajax(lkChapter(d.chapter_id, key))).data || d; } catch (e) {}
}
if (d.locked == 1 && key) {
    reload();
    if (d.locked == 1 && d.access_type == 'coin' && coinOn) {
        try {
            var u = JSON.parse(java.ajax(lkUrl('/new-content-read/unlock-chapter', {chapter_id: d.chapter_id}, key, true)));
            if (u.code == 0) reload();
            else err = String((u.data && u.data.message) || u.message || 'code ' + u.code);
        } catch (e) { err = String(e); }
    }
}
var out = lkHtml(d);
if (d.locked == 1) out = (out ? out + '\n' : '') + lkLockTip(d, !!key, coinOn, err);
else if (!out) out = '⚠️ 本章暂无内容';
if (lkZhOn(source)) out = String(java.t2s(out));
